{"file_path":"src/address.js","content":"/**
 * Cell addresses: one or two letters naming a column (A..Z, then AA..ZZ)
 * followed by one to three digits naming a row of at least 1.
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Column letters (A..Z, AA..ZZ) to their 1-based ordinal. */
function colToNum(letters) {
  if (letters.length === 1) {
    return letters.charCodeAt(0) - 64
  }
  const c1 = letters.charCodeAt(0) - 64
  const c2 = letters.charCodeAt(1) - 64
  return 26 + (c1 - 1) * 26 + c2
}

/** Inverse of colToNum: a 1-based column ordinal to its letters. */
function numToCol(n) {
  if (n <= 26) {
    return String.fromCharCode(64 + n)
  }
  const rest = n - 26 - 1
  const c1 = Math.floor(rest / 26) + 1
  const c2 = (rest % 26) + 1
  return String.fromCharCode(64 + c1) + String.fromCharCode(64 + c2)
}

/**
 * Parses a word as a cell address. Returns null when the word is not one or
 * two letters followed by one to three digits naming a row of at least 1,
 * which is how an address outside the addressable range is recognised.
 */
function parseAddress(word) {
  const m = ADDRESS_RE.exec(word)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToNum(m[1].toUpperCase())
  return { col, row, canonical: m[1].toUpperCase() + row }
}

function addressOf(col, row) {
  return numToCol(col) + row
}

module.exports = { parseAddress, addressOf, colToNum, numToCol }
"}

