{"file_path":"src/lexer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

const TWO_CHAR_OPS = ['<=', '>=', '<>']
const ONE_CHAR_OPS = '()+-*/^=<>,:'

/**
 * Splits a formula body into tokens, skipping spaces and tabs. Returns null
 * when a character does not belong to any token, which makes the formula
 * grammatically invalid.
 */
function tokenize(str) {
  const tokens = []
  let i = 0
  const n = str.length
  while (i < n) {
    const c = str[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c >= '0' && c <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(str.slice(i))
      tokens.push({ type: 'number', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = /^[A-Za-z]+[0-9]*/.exec(str.slice(i))
      tokens.push({ type: 'word', value: m[0] })
      i += m[0].length
      continue
    }
    const two = str.slice(i, i + 2)
    if (TWO_CHAR_OPS.includes(two)) {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if (ONE_CHAR_OPS.includes(c)) {
      tokens.push({ type: 'op', value: c })
      i++
      continue
    }
    return null
  }
  return tokens
}

export { tokenize }
"}

