{"file_path":"src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies, producing an AST or throwing
 * ParseFail when the token stream does not match the grammar.
 *
 * Precedence, loosest to tightest: comparisons, then `+`/`-`, then `*`/`/`,
 * then `^` (right-associative), then a leading `-`/`+` (tighter than `^`).
 * A range (`A1:B3`) is only accepted directly as a function-call argument.
 */

const COMPARISON_OPS = ['=', '<>', '<', '<=', '>', '>=']

class ParseFail extends Error {}

function parseFormula(tokens) {
  let pos = 0

  function peek() {
    return tokens[pos]
  }

  function next() {
    return tokens[pos++]
  }

  function expectOp(value) {
    const t = peek()
    if (!t || t.type !== 'op' || t.value !== value) throw new ParseFail()
    return next()
  }

  function parseExpression() {
    return parseComparison()
  }

  function parseComparison() {
    let left = parseAdditive()
    for (;;) {
      const t = peek()
      if (t && t.type === 'op' && COMPARISON_OPS.includes(t.value)) {
        next()
        const right = parseAdditive()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  function parseAdditive() {
    let left = parseMultiplicative()
    for (;;) {
      const t = peek()
      if (t && t.type === 'op' && (t.value === '+' || t.value === '-')) {
        next()
        const right = parseMultiplicative()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  function parseMultiplicative() {
    let left = parsePower()
    for (;;) {
      const t = peek()
      if (t && t.type === 'op' && (t.value === '*' || t.value === '/')) {
        next()
        const right = parsePower()
        left = { type: 'binop', op: t.value, left, right }
      } else break
    }
    return left
  }

  function parsePower() {
    const base = parseUnary()
    const t = peek()
    if (t && t.type === 'op' && t.value === '^') {
      next()
      const right = parsePower()
      return { type: 'binop', op: '^', left: base, right }
    }
    return base
  }

  function parseUnary() {
    const t = peek()
    if (t && t.type === 'op' && (t.value === '-' || t.value === '+')) {
      next()
      const operand = parseUnary()
      return { type: 'unary', op: t.value, operand }
    }
    return parsePrimary()
  }

  function parsePrimary() {
    const t = peek()
    if (!t) throw new ParseFail()
    if (t.type === 'number') {
      next()
      return { type: 'number', value: parseFloat(t.value) }
    }
    if (t.type === 'op' && t.value === '(') {
      next()
      const e = parseExpression()
      expectOp(')')
      return e
    }
    if (t.type === 'word') {
      next()
      const upper = t.value.toUpperCase()
      const nt = peek()
      if (nt && nt.type === 'op' && nt.value === '(') {
        next()
        const args = parseArgList()
        expectOp(')')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', word: t.value }
    }
    throw new ParseFail()
  }

  function parseArgList() {
    const args = []
    const t = peek()
    if (t && t.type === 'op' && t.value === ')') return args
    args.push(parseArg())
    for (;;) {
      const t2 = peek()
      if (t2 && t2.type === 'op' && t2.value === ',') {
        next()
        args.push(parseArg())
      } else break
    }
    return args
  }

  function parseArg() {
    const t = peek()
    if (t && t.type === 'word') {
      const t2 = tokens[pos + 1]
      if (t2 && t2.type === 'op' && t2.value === ':') {
        const from = next().value
        next()
        const t3 = peek()
        if (!t3 || t3.type !== 'word') throw new ParseFail()
        const to = next().value
        return { type: 'range', from, to }
      }
    }
    return parseExpression()
  }

  const result = parseExpression()
  if (pos !== tokens.length) throw new ParseFail()
  return result
}

export { parseFormula, ParseFail }
"}

