    }
    if (t.type === 'word') {
      next()
      const upper = t.value.toUpperCase()
      const nt = peek()
      if (nt && nt.type === 'op' && nt.value === '(') {
        next()
        const args = parseArgList()
        expectOp(')')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'ref', word: t.value }
    }
    throw new ParseFail()
  }

  function parseArgList() {
    const args = []
    const t = peek()
    if (t && t.type === 'op' && t.value === ')') return args
    args.push(parseArg())
    for (;;) {
      const t2 = peek()
      if (t2 && t2.type === 'op' && t2.value === ',') {
        next()
        args.push(parseArg())
      } else break
    }
    return args
  }

  function parseArg() {
    const t = peek()
    if (t && t.type === 'word') {
      const t2 = tokens[pos + 1]
      if (t2 && t2.type === 'op' && t2.value === ':') {
        const from = next().value
        next()
        const t3 = peek()
        if (!t3 || t3.type !== 'word') throw new ParseFail()
