{"file_path":"src/sheet.js","content":"/**
 * Parses raw sheet text into declared cells, as described in the task: split
 * on newlines and drop the trailing empty tail, strip leading spaces/tabs
 * from each line, skip blank lines and comment lines, then split the
 * remainder into an address and verbatim content.
 */

import { parseAddress } from './address.js'

class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  lines.forEach((rawLine, i) => {
    const lineNo = i + 1
    const stripped = rawLine.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) return

    const m = /^(\S+)[ \t]*([\s\S]*)$/.exec(stripped)
    const addrToken = m[1]
    const content = m[2]

    const addr = parseAddress(addrToken)
    if (!addr) {
      throw new SheetError(lineNo, `invalid cell address ${addrToken}`)
    }
    if (cells.has(addr.canonical)) {
      throw new SheetError(lineNo, `cell ${addr.canonical} is declared twice`)
    }
    cells.set(addr.canonical, { content, col: addr.col, row: addr.row })
  })

  return cells
}

export { parseSheet, SheetError }
"}

