{"file_path":"src/values.js","content":"/** The four value kinds a formula or literal can produce. */

function numberValue(n) {
  return { type: 'number', value: n }
}

function textValue(s) {
  return { type: 'text', value: s }
}

function boolValue(b) {
  return { type: 'boolean', value: b }
}

function errorValue(token) {
  return { type: 'error', value: token }
}

/** DIV/0! covers both a zero divisor and any non-finite arithmetic result. */
function finiteOrDiv0(n) {
  return Number.isFinite(n) ? numberValue(n) : errorValue('#DIV/0!')
}

/** Reads a value as a number for arithmetic: booleans are 1/0, text is #VALUE!. */
function asNumberOrError(v) {
  if (v.type === 'number') return v
  if (v.type === 'boolean') return numberValue(v.value ? 1 : 0)
  if (v.type === 'text') return errorValue('#VALUE!')
  return v // error passes through unchanged
}

/** A number printed as JavaScript would, after rounding to 10 significant digits. */
function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

function formatValue(v) {
  if (v.type === 'number') return formatNumber(v.value)
  if (v.type === 'boolean') return v.value ? 'TRUE' : 'FALSE'
  return v.value // text or error token, printed as itself
}

export { numberValue, textValue, boolValue, errorValue, finiteOrDiv0, asNumberOrError, formatValue }
"}

