{"file_path":"src/evaluate.js","content":"/**
 * Turns declared cells into an evaluator that computes each cell's value
 * (with cycle detection) and, independently, each cell's direct dependencies.
 */

import { tokenize } from './lexer.js'
import { parseFormula, ParseFail } from './parser.js'
import { parseAddress, addressOf } from './address.js'
import { numberValue, textValue, boolValue, errorValue, finiteOrDiv0, asNumberOrError } from './values.js'

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])
const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/
const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])
const CALL_ARITY = { SUM: 'multi', MIN: 'multi', MAX: 'multi', AVG: 'multi', COUNT: 'multi', ABS: 1, IF: 3 }

/** Parses a cell's raw content into a literal or a formula AST, once. */
function parseCell(content) {
  if (!content.startsWith('=')) return { kind: 'literal', text: content }
  const tokens = tokenize(content.slice(1))
  if (tokens === null) return { kind: 'invalid' }
  try {
    const ast = parseFormula(tokens)
    return { kind: 'formula', ast }
  } catch (e) {
    if (e instanceof ParseFail) return { kind: 'invalid' }
    throw e
  }
}

function evalLiteral(text) {
  if (text === '') return numberValue(0)
  if (ERROR_TOKENS.has(text)) return errorValue(text)
  if (NUMBER_RE.test(text)) return numberValue(parseFloat(text))
  return textValue(text)
}

function rangeCells(from, to) {
  const a = parseAddress(from)
  const b = parseAddress(to)
  if (!a || !b) return null
  const colMin = Math.min(a.col, b.col)
  const colMax = Math.max(a.col, b.col)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const cells = []
  for (let col = colMin; col <= colMax; col++) {
    for (let row = rowMin; row <= rowMax; row++) {
      cells.push(addressOf(col, row))
    }
  }
  return cells
}

/** Compares two non-error values per the task's cross-kind ordering. */
function compareValues(l, r) {
  const rank = (v) => (v.type === 'number' ? 0 : v.type === 'text' ? 1 : 2)
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl - rr
  if (l.type === 'number') return l.value - r.value
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  const lv = l.value ? 1 : 0
  const rv = r.value ? 1 : 0
  return lv - rv
}

function compare(op, l, r) {
  const cmp = compareValues(l, r)
  switch (op) {
    case '=': return boolValue(cmp === 0)
    case '<>': return boolValue(cmp !== 0)
    case '<': return boolValue(cmp < 0)
    case '<=': return boolValue(cmp <= 0)
    case '>': return boolValue(cmp > 0)
    case '>=': return boolValue(cmp >= 0)
  }
}

class Evaluator {
  constructor(cells) {
    this.cells = cells // Map address -> { content, col, row }
    this.parsed = new Map() // address -> parseCell result, memoized
    this.cache = new Map() // address -> value, memoized
    this.state = new Map() // address -> 'visiting' | 'done'
  }

  getParsed(addr) {
    if (!this.parsed.has(addr)) {
      this.parsed.set(addr, parseCell(this.cells.get(addr).content))
    }
    return this.parsed.get(addr)
  }

  evaluateCell(addr) {
    if (this.cache.has(addr)) return this.cache.get(addr)
    if (!this.cells.has(addr)) {
      const v = numberValue(0)
      this.cache.set(addr, v)
      return v
    }
    if (this.state.get(addr) === 'visiting') return errorValue('#CYCLE!')

    this.state.set(addr, 'visiting')
    const parsed = this.getParsed(addr)
    let result
    if (parsed.kind === 'literal') result = evalLiteral(parsed.text)
    else if (parsed.kind === 'invalid') result = errorValue('#ERR!')
    else result = this.evalNode(parsed.ast)
    this.state.set(addr, 'done')
    this.cache.set(addr, result)
    return result
  }

  /** A scalar argument position: a range there is grammatically accepted but is not a value. */
  evalScalarArg(node) {
    if (node.type === 'range') return errorValue('#ERR!')
    return this.evalNode(node)
  }

  evalRange(node) {
    const cells = rangeCells(node.from, node.to)
    if (!cells) return [errorValue('#REF!')]
    return cells.map((addr) => this.evaluateCell(addr))
  }

  evalNode(node) {
    switch (node.type) {
      case 'number':
        return numberValue(node.value)
      case 'bool':
        return boolValue(node.value)
      case 'ref': {
        const addr = parseAddress(node.word)
        if (!addr) return errorValue('#REF!')
        return this.evaluateCell(addr.canonical)
      }
      case 'unary': {
        const v = this.evalNode(node.operand)
        if (v.type === 'error') return v
        const n = asNumberOrError(v)
        if (n.type === 'error') return n
        return finiteOrDiv0(node.op === '-' ? -n.value : n.value)
      }
      case 'binop':
        return this.evalBinop(node)
      case 'call':
        return this.evalCall(node)
      default:
        throw new Error(`unreachable node type ${node.type}`)
    }
  }

  evalBinop(node) {
    const l = this.evalNode(node.left)
    if (l.type === 'error') return l
    const r = this.evalNode(node.right)
    if (r.type === 'error') return r

    if (COMPARISON_OPS.has(node.op)) return compare(node.op, l, r)

    const ln = asNumberOrError(l)
    if (ln.type === 'error') return ln
    const rn = asNumberOrError(r)
    if (rn.type === 'error') return rn

    switch (node.op) {
      case '+': return finiteOrDiv0(ln.value + rn.value)
      case '-': return finiteOrDiv0(ln.value - rn.value)
      case '*': return finiteOrDiv0(ln.value * rn.value)
      case '/':
        if (rn.value === 0) return errorValue('#DIV/0!')
        return finiteOrDiv0(ln.value / rn.value)
      case '^':
        return finiteOrDiv0(Math.pow(ln.value, rn.value))
    }
  }

  evalCall(node) {
    const { name, args } = node
    if (!(name in CALL_ARITY)) return errorValue('#NAME?')
    const arity = CALL_ARITY[name]
    if (arity === 'multi') {
      if (args.length < 1) return errorValue('#ERR!')
    } else if (args.length !== arity) {
      return errorValue('#ERR!')
    }

    if (name === 'IF') {
      const cond = this.evalScalarArg(args[0])
