{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluate.js'
import { formatValue } from './values.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) {
      fail(`line ${e.line}: ${e.message}`)
      return
    }
    throw e
  }

  const addresses = [...cells.entries()]
    .sort(([, a], [, b]) => a.col - b.col || a.row - b.row)
    .map(([addr]) => addr)

  const evaluator = new Evaluator(cells)
  const lines = []
  if (mode === 'values') {
    for (const addr of addresses) {
      lines.push(`${addr}=${formatValue(evaluator.evaluateCell(addr))}`)
    }
  } else {
    for (const addr of addresses) {
      const deps = evaluator.dependenciesOf(addr)
      lines.push(`${addr}:${deps.map((d) => ` ${d}`).join('')}`)
    }
  }
  process.stdout.write(lines.map((l) => l + '\n').join(''))
}

main()
"}

